llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Alpidem showed an absolute oral bioavailability of 32 ± 2% in young human subjects after a 50-mg tablet, which is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Tasimelteon had a mean absolute oral bioavailability of 38% after oral administration in humans, with a 90% confidence interval of 27–54%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Meptazinol showed a mean absolute oral bioavailability of 8.69 ± 1.61% in male human volunteers after a 200-mg oral dose versus IV, which is below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer human absolute bioavailability records are above 20% (e.g., 32%, 38%, 52.7%, 60%, 80%), while one high-transfer record is clearly below 20% (meptazinol ~9%). The preponderance of direct human absolute F evidence supports high bioavailability.",
  "evidence_gaps": [
    "The evidence set is not unanimous: one high-transfer molecule (meptazinol) has low absolute oral bioavailability, creating residual uncertainty.",
    "No additional records directly resolve the conflict between the many positive human F measurements and the single negative human F measurement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

